import{_ as a,o as i,c as l,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Закон о Гарантии Медицинского Обеспечения","description":"","frontmatter":{},"headers":[],"relativePath":"ru/44-医疗保障法.md","filePath":"ru/44-医疗保障法.md"}'),d={name:"ru/44-医疗保障法.md"};function e(o,t,h,n,s,u){return i(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="закон-о-гарантии-медицинского-обеспечения" tabindex="-1">Закон о Гарантии Медицинского Обеспечения <a class="header-anchor" href="#закон-о-гарантии-медицинского-обеспечения" aria-label="Permalink to &quot;Закон о Гарантии Медицинского Обеспечения&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>44</td></tr><tr><td>Модуль</td><td>Правовая система и структура управления</td></tr><tr><td>Ключевые слова</td><td>Право на медицинскую помощь, Симбиотическая медицина, Лечение культивационных травм, Жизнь и здоровье, Система медицинского страхования</td></tr></tbody></table><h2 id="i-цель-законодательства-и-основные-принципы" tabindex="-1">I. Цель законодательства и основные принципы <a class="header-anchor" href="#i-цель-законодательства-и-основные-принципы" aria-label="Permalink to &quot;I. Цель законодательства и основные принципы&quot;">​</a></h2><p><em>Закон о Гарантии Медицинского Обеспечения</em> — один из пяти вспомогательных законов Симбиотической Цивилизации Якоря. Он направлен на гарантию права на здоровье и медицинскую помощь всех жизней во Вселенной Хэнъюань, создание симбиотической медицинской системы, охватывающей все расы, и обеспечение каждому существу своевременного и эффективного лечения при травмах и болезнях.</p><p>Настоящий Закон устанавливает следующие основные принципы:</p><table tabindex="0"><thead><tr><th>Принцип</th><th>Содержание</th></tr></thead><tbody><tr><td>Приоритет здоровья</td><td>Жизнь и здоровье — основа всякой эволюции; государство и цивилизация ставят защиту жизни и здоровья на приоритетное место</td></tr><tr><td>Всеобщий охват</td><td>Медицинское обеспечение охватывает все жизни независимо от расы, культивации, происхождения и экономического положения</td></tr><tr><td>Иерархическая диагностика и лечение</td><td>Создание трёхуровневой системы диагностики и лечения — базовая медицина, региональная медицина, высшая медицина — с рациональным распределением медицинских ресурсов</td></tr><tr><td>Сочетание профилактики и лечения</td><td>Профилактика прежде всего, сочетание профилактики и лечения; внимание к профилактике и реабилитации культивационных травм</td></tr><tr><td>Адаптация иных рас</td><td>Предоставление адаптированных медицинских планов с учётом физиологических особенностей различных рас; запрет единообразного применения человеческих стандартов</td></tr><tr><td>Атрибут общественного блага</td><td>Базовые медицинские услуги имеют атрибут общественного блага; право на лечение не может отниматься в целях извлечения прибыли</td></tr></tbody></table><h2 id="ii-правовые-гарантии-права-на-жизнь-и-здоровье" tabindex="-1">II. Правовые гарантии права на жизнь и здоровье <a class="header-anchor" href="#ii-правовые-гарантии-права-на-жизнь-и-здоровье" aria-label="Permalink to &quot;II. Правовые гарантии права на жизнь и здоровье&quot;">​</a></h2><p>Настоящий Закон прямо устанавливает, что право на жизнь и здоровье — основное право, предоставленное каждой жизни Симбиотической Конституцией, и включает:</p><ol><li><strong>Право на базовую медицинскую помощь</strong>: каждое существо имеет право на бесплатные базовые медицинские услуги, включая диагностику и лечение распространённых заболеваний, базовые лекарства, регулярные медицинские осмотры и т.д.</li><li><strong>Право на неотложную помощь</strong>: каждое существо при внезапной травме или болезни имеет право на экстренное лечение; медицинские учреждения не вправе отказывать в экстренной помощи по каким-либо причинам.</li><li><strong>Право на лечение культивационных травм</strong>: культиваторы, получившие во время культивации такие травмы, как энергетические расстройства, повреждения меридианов, отклонение культивации и т.п., имеют право на профессиональное лечение.</li><li><strong>Право на информированное согласие</strong>: пациенты имеют право знать своё состояние, план лечения, риски и прогноз, а также право выбирать или отказываться от планов лечения.</li><li><strong>Право на защиту конфиденциальности</strong>: медицинская информация и данные о теле пациента защищены законом; без согласия пациента они не могут разглашаться или использоваться в иных целях.</li><li><strong>Право на гарантию реабилитации</strong>: травмированные и больные имеют право на реабилитационное лечение и вспомогательные устройства, помогающие восстановить трудовые и бытовые способности.</li></ol><h2 id="iii-архитектура-симбиотическои-медицинскои-системы" tabindex="-1">III. Архитектура симбиотической медицинской системы <a class="header-anchor" href="#iii-архитектура-симбиотическои-медицинскои-системы" aria-label="Permalink to &quot;III. Архитектура симбиотической медицинской системы&quot;">​</a></h2><p>Медицинская система Симбиотической Цивилизации Якоря делится на три уровня, между которыми установлены механизмы направления и сотрудничества:</p><table tabindex="0"><thead><tr><th>Уровень</th><th>Название</th><th>Функции</th><th>Охват</th></tr></thead><tbody><tr><td>Первый уровень</td><td>Базовая медицинская станция</td><td>Диагностика и лечение распространённых заболеваний, профилактическое здравоохранение, базовые осмотры, экстренная транспортировка</td><td>Сообщества/деревни/малые плоскости</td></tr><tr><td>Второй уровень</td><td>Региональный медицинский центр</td><td>Специализированная диагностика и лечение, хирургическое лечение, первичная обработка культивационных травм, реабилитация</td><td>Города/регионы/средние плоскости</td></tr><tr><td>Третий уровень</td><td>Высшая медицинская больница</td><td>Трудные и тяжёлые заболевания, продвинутые культивационные травмы, болезни области сознания, сложные межрасовые заболевания</td><td>Ядро цивилизации/крупные плоскости</td></tr></tbody></table><p>Кроме того, создана «Специализация по культивационным травмам»: специально занимается всеми видами травм во время культивации, включая энергетическую перегрузку, разрыв меридианов, вторжение сердечных демонов, душевные травмы и т.д., с медицинским персоналом, сведущим в законах культивации.</p><h2 id="iv-фонд-медицинского-обеспечения" tabindex="-1">IV. Фонд медицинского обеспечения <a class="header-anchor" href="#iv-фонд-медицинского-обеспечения" aria-label="Permalink to &quot;IV. Фонд медицинского обеспечения&quot;">​</a></h2><p>Фонд медицинского обеспечения — экономическая основа функционирования симбиотической медицинской системы, его источники включают:</p><ul><li>Ассигнования из общественного фонда накопления (основной источник)</li><li>Отчисления на медицинское обеспечение в Механизме Совместного Подряда</li><li>Социальные пожертвования</li><li>Доходы от инвестиций фонда</li></ul><p>Сфера выплат фонда включает: расходы на базовые медицинские услуги, расходы на экстренную помощь, расходы на лечение культивационных травм, расходы на базовые лекарства, расходы на реабилитацию и т.д. Пациенты оплачивают лишь небольшую часть расходов из собственных средств; для лиц с финансовыми трудностями предусмотрены скидки и освобождения.</p><h2 id="v-медицинские-учреждения-и-медицинскии-персонал" tabindex="-1">V. Медицинские учреждения и медицинский персонал <a class="header-anchor" href="#v-медицинские-учреждения-и-медицинскии-персонал" aria-label="Permalink to &quot;V. Медицинские учреждения и медицинский персонал&quot;">​</a></h2><ul><li><strong>Государственные медицинские учреждения</strong>: учреждаются государством или сообществом цивилизации, выполняют базовые медицинские услуги и функции общественного здравоохранения, финансирование обеспечивается Фондом медицинского обеспечения.</li><li><strong>Частные медицинские учреждения</strong>: учреждаются общественными силами в соответствии с законом; могут предоставлять высококлассные медицинские услуги, но обязаны принимать надзор компетентных медицинских органов и не вправе отказывать пациентам в экстренной помощи.</li><li><strong>Медицинские учреждения иных рас</strong>: специализированные медицинские учреждения, созданные с учётом физиологических потребностей особых рас, с медицинским персоналом иных рас.</li><li><strong>Права и обязанности медицинского персонала</strong>: медицинский персонал пользуется правами на защиту практики, разумное вознаграждение, профессиональное обучение и т.д., а также несёт обязанности спасать умирающих и лечить раненых, уважать пациентов, хранить медицинскую тайну и т.д.</li></ul><h2 id="vi-общественное-здравоохранение-и-профилактика" tabindex="-1">VI. Общественное здравоохранение и профилактика <a class="header-anchor" href="#vi-общественное-здравоохранение-и-профилактика" aria-label="Permalink to &quot;VI. Общественное здравоохранение и профилактика&quot;">​</a></h2><p>Государство создаёт систему общественного здравоохранения, выполняющую следующие функции:</p><ol><li>Мониторинг и профилактика инфекционных заболеваний, создание межплоскостного механизма предупреждения эпидемий.</li><li>Всеобщие медицинские осмотры и управление медицинскими картами.</li><li>Пропаганда безопасности культивации и рекомендации по профилактике культивационных травм.</li><li>Контроль гигиены окружающей среды и безопасности продуктов питания и лекарств.</li><li>Экстренное реагирование на чрезвычайные ситуации в области общественного здравоохранения.</li></ol><h2 id="vii-юридическая-ответственность" tabindex="-1">VII. Юридическая ответственность <a class="header-anchor" href="#vii-юридическая-ответственность" aria-label="Permalink to &quot;VII. Юридическая ответственность&quot;">​</a></h2><p>Действия, нарушающие положения настоящего Закона, в зависимости от тяжести обстоятельств несут следующую ответственность:</p><ul><li>Медицинские учреждения, отказавшие пациентам в экстренной помощи, — предписание исправить и штраф; при наступлении тяжёлых последствий — аннулирование лицензии на практику.</li><li>Медицинский персонал, чья грубая небрежность причинила вред пациентам, — ответственность за возмещение; при серьёзных обстоятельствах — лишение квалификации на практику.</li><li>Медицинские учреждения, незаконно взимающие плату или оказывающие избыточное лечение, — предписание вернуть плату и штраф.</li><li>Разглашение медицинской тайны пациента — компенсация морального вреда; при серьёзных обстоятельствах — уголовная ответственность.</li><li>Производство и продажа поддельных и недоброкачественных лекарств — конфискация незаконного дохода и штраф; при наличии состава преступления — уголовная ответственность.</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p><em>Закон о Гарантии Медицинского Обеспечения</em> — воплощение философии «дорога для каждого» Симбиотической Цивилизации Якоря в области здоровья. Создавая медицинскую систему всеобщего охвата, учреждая специализацию по культивационным травмам и гарантируя право на экстренную помощь, он обеспечивает каждому существу своевременное лечение при травмах и болезнях, закладывая прочный фундамент здоровья для совместного продвижения Десяти Тысяч Рас.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Симбиотическая Конституция: Общие Принципы)</li><li>38-共生医疗体系 (Симбиотическая медицинская система)</li><li>45-住房保障法 (Закон о Гарантии Жилья)</li><li>08-人人有路保障体系 (Система Гарантии Дороги Для Каждого)</li></ul>',29)])])}const p=a(d,[["render",e]]);export{c as __pageData,p as default};
